                .get("transferId").asText();
        revoke(f.sourceCustodian(), transferId, uniqueKey("CMD"),
                f.orderVersion(), f.sourceCustodian(), f.targetCustodian());

        MvcResult result = mockMvc.perform(get("/api/evidence/{key}/case-links", ev))
                .andReturn();
